/**
 * Stylesheet imports resolve to the raw CSS text, not to a side effect:
 * esbuild inlines them with `--loader:.css=text`, Vite resolves `?inline` to the
 * stylesheet text, and Vitest returns the content through `test.css: true`.
 */

declare module '*.css?inline' {
  const css: string;
  export default css;
}

declare module '*.css' {
  const css: string;
  export default css;
}

/* Hooks: --an-checkbox-group-gap.
   Colours and scales come from @an-ui-kit/tokens, each with a literal fallback. */

:host {
  display: block;
  color-scheme: light dark;
}

:host([data-theme='dark']) {
  color-scheme: dark;
}

:host([data-theme='light']) {
  color-scheme: light;
}

.base {
  display: flex;
  flex-direction: column;
  gap: var(--an-space-2, 0.5rem);
  font-family: inherit;
}

.label {
  color: var(--an-color-fg-1, #18181b);
  font-size: var(--an-font-size-sm, 0.875rem);
  line-height: 1.4;
}

.group {
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
  gap: var(--an-checkbox-group-gap, var(--an-space-2, 0.5rem));
}

:host([orientation='horizontal']) .group {
  flex-direction: row;
  align-items: center;
}

:host([disabled]) .base {
  opacity: 0.6;
}

/* Guards against page-level preflight (e.g. Tailwind v4) leaking into the host. */
:host {
  box-sizing: border-box;
  border: 0 solid;
  margin: 0;
  line-height: 1.5;
}

import resetStyles from './reset.css?inline';

/** Values allowed for attribute-backed properties. */
export type Primitive = string | number | boolean;

/** Defaults for attribute-backed properties; keys define the public API. */
export type Defaults = Record<string, Primitive>;

/** Defaults for list properties; an attribute holds the items comma-separated. */
export type ArrayDefaults = Record<string, string[]>;

/** `my-attr` -> `myAttr`, so an attribute can drive the camelCase property. */
function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase());
}

/** `myAttr` -> `my-attr`, so a property can reflect to the attribute. */
function toKebabCase(name: string): string {
  return name.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

/** `"a, b"` -> `['a', 'b']`; an absent attribute restores the fallback list. */
function toList(value: string | null, fallback: readonly string[]): string[] {
  if (value === null) return [...fallback];
  return value
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

/** Order-sensitive comparison, used to skip redundant writes and renders. */
function sameList(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && a.every((part, index) => part === b[index]);
}

/**
 * Dependency-free base class for every `an-*` custom element.
 *
 * Contract:
 * - Constructor only touches `this` (`attachShadow`, `attachInternals`, local
 *   fields, accessors): it never reads `document`, `window`, storage or the
 *   network, so importing a component stays safe under SSR and inside workers.
 * - `static defaults` declares the attribute-backed API. Property accessors are
 *   generated from it and reflect back to attributes, so `el.variant` and
 *   `variant="primary"` can never disagree; attributes stay the source of truth.
 * - Markup comes from `render()` as an HTML string and is written straight into
 *   the shadow root, including `static styles` plus the shared reset.
 * - Listeners belong on the shadow root (event delegation), because re-rendering
 *   replaces the inner markup.
 * - Every write re-renders before it returns, so `el.disabled = true` followed by
 *   a synchronous `shadowRoot` read already sees the new markup.
 * - Form participation is opt-in: a subclass sets `static formAssociated = true`
 *   and then gets `this.internals`, the platform lifecycle callbacks
 *   (`formAssociatedCallback`, `formResetCallback`, `formDisabledCallback`) and
 *   the protected `onFormReset` / `onFormDisabled` hooks.
 * - `static arrayDefaults` opts an attribute into a comma-separated `string[]`
 *   property. Elements that do not declare it keep a scalar-only API.
 * - `checkValidity()` / `reportValidity()` / `reset()` / `getFormData()` wrap the
 *   platform form surface so a subclass does not repeat it.
 */
export abstract class AnElement extends HTMLElement {
  /** Shadow-DOM stylesheet source for this element. */
  static styles: string = '';

  /** Attribute-backed properties and their defaults. */
  static defaults: Defaults = {};

  /**
   * Array-backed properties and their defaults. The attribute holds the items
   * comma-separated (`items="a, b"`); the property is a `string[]`.
   */
  static arrayDefaults: ArrayDefaults = {};

  /** Attributes the browser reports to `attributeChangedCallback`. */
  static get observedAttributes(): string[] {
    return [
      ...Object.keys(this.defaults).map(toKebabCase),
      ...Object.keys(this.arrayDefaults).map(toKebabCase),
    ];
  }

  /**
   * Opts the element into `ElementInternals` form participation.
   * Subclasses that submit/reset/validate through a form set this to `true`.
   */
  static formAssociated: boolean = false;

  /**
   * Platform form internals, attached only when `static formAssociated` is
   * `true`. `null` on elements that did not opt in and on DOM implementations
   * without `attachInternals()`.
   */
  protected internals: ElementInternals | null = null;

  #defaults: Defaults = {};
  #values: Record<string, Primitive> = {};
  #arrayDefaults: ArrayDefaults = {};
  #arrays: Record<string, string[]> = {};
  #rendered = false;
  #reflecting = false;
  #fallbackStyle: HTMLStyleElement | null = null;

  constructor() {
    super();
    const ctor = this.constructor as typeof AnElement;
    const root = this.attachShadow({ mode: 'open' });

    if (ctor.formAssociated) {
      try {
        this.internals = this.attachInternals();
      } catch {
        // `attachInternals()` throws unless the element opted in, and some DOM
        // implementations (e.g. happy-dom) do not expose it at all: degrade to a
        // plain element instead of failing construction.
        this.internals = null;
      }
    }

    this.#defaults = ctor.defaults;
    this.#values = { ...ctor.defaults };
    this.#arrayDefaults = ctor.arrayDefaults;
    this.#arrays = {};
    for (const key of Object.keys(ctor.arrayDefaults)) {
      this.#arrays[key] = [...ctor.arrayDefaults[key]];
    }
    this.#adoptStyles(root, `${resetStyles}\n${ctor.styles}`);

    for (const [key, fallback] of Object.entries(ctor.defaults)) {
      const type = typeof fallback;
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => this.#values[key],
        set: (next: Primitive) => this.#assign(key, next, type),
      });
    }

    for (const key of Object.keys(ctor.arrayDefaults)) {
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => [...(this.#arrays[key] ?? [])],
        set: (next: string[] | string) => this.#assignList(key, next),
      });
    }
  }

  connectedCallback(): void {
    if (!this.#rendered) {
      this.#rendered = true;
      this.requestUpdate();
    }
    this.onConnect();
  }

  /** Re-renders the shadow root from `render()`. */
  requestUpdate(): void {
    const root = this.shadowRoot;
    if (!root || !this.#rendered) return;
    root.innerHTML = this.render();
    if (this.#fallbackStyle && !this.#fallbackStyle.isConnected) root.prepend(this.#fallbackStyle);
    this.afterRender();
  }

  disconnectedCallback(): void {
    this.onDisconnect();
  }

  /**
   * Platform callback: the element was associated with, or disassociated from,
   * a form. Association itself is opt-in, so the default implementation is a
   * no-op; a subclass may read `this.internals?.form` here.
   */
  formAssociatedCallback(): void {}

  /** Platform callback: the owning form was reset. */
  formResetCallback(): void {
    this.onFormReset();
  }

  /** Platform callback: the platform disabled or enabled the element. */
  formDisabledCallback(disabled: boolean): void {
    this.onFormDisabled(disabled);
  }

  /**
   * Constraint validation in the owning form. Forwards to `ElementInternals`
   * when available; without internals there is nothing to validate, so it
   * reports `true`.
   */
  checkValidity(): boolean {
    const internals = this.internals;
    if (!internals || typeof internals.checkValidity !== 'function') return true;
    return internals.checkValidity();
  }

  /** Like `checkValidity()`, but asks the platform to report the problem. */
  reportValidity(): boolean {
    const internals = this.internals;
    if (!internals || typeof internals.reportValidity !== 'function') return true;
    return internals.reportValidity();
  }

  /**
   * Resets the control to the state it was mounted with and re-renders.
   * Delegates to `formResetCallback()` so a subclass only overrides
   * `onFormReset()`.
   */
  reset(): void {
    this.formResetCallback();
    this.requestUpdate();
  }

  /**
   * Serializes this element the way `new FormData(form)` would: one row per
   * `formEntries()` entry, or `null` when the element submits nothing.
   */
  getFormData(): FormData | null {
    const entries = this.formEntries();
    if (entries.length === 0) return null;
    const data = new FormData();
    for (const [name, value] of entries) data.append(name, value);
    return data;
  }

  /**
   * Rows this element contributes to `FormData`. Defaults to `name` + `value`
   * when both are usable; subclasses with a richer payload override it.
   */
  protected formEntries(): Array<[string, string | File]> {
    const { name, value } = this as unknown as { name?: unknown; value?: unknown };
    if (typeof name !== 'string' || name.length === 0) return [];
    if (typeof value !== 'string' && typeof value !== 'number') return [];
    return [[name, String(value)]];
  }

  /** Hook: connected and rendered; default no-op. */
  protected onConnect(): void {}

  /** Hook: disconnected from the document; default no-op. */
  protected onDisconnect(): void {}

  /** Hook: the owning form was reset; restore state here. Default no-op. */
  protected onFormReset(): void {}

  /** Hook: the platform-level disabled state changed; default no-op. */
  protected onFormDisabled(disabled: boolean): void {}

  /** Returns the shadow-DOM markup; called on connect and after every change. */
  protected abstract render(): string;

  /** Hook for state markup cannot express (e.g. `.disabled` on a child node). */
  protected afterRender(): void {}

  /** Dispatches a bubbling, composed `CustomEvent`. */
  emit<T>(name: string, detail?: T): boolean {
    return this.dispatchEvent(new CustomEvent<T>(name, { bubbles: true, composed: true, detail }));
  }

  attributeChangedCallback(name: string, oldValue: string | null, value: string | null): void {
    if (oldValue === value) return;
    const key = toCamelCase(name);
    if (key in this.#arrayDefaults) {
      this.#arrays[key] = toList(value, this.#arrayDefaults[key]); // attribute -> list property
      if (this.#rendered && !this.#reflecting) this.requestUpdate();
      return;
    }
    if (!(key in this.#defaults)) return;
    this.#values[key] = this.#coerce(key, value); // attribute -> camelCase property
    if (this.#rendered && !this.#reflecting) this.requestUpdate();
  }

  #assignList(key: string, next: string[] | string): void {
    const value = Array.isArray(next)
      ? next.map((part) => String(part).trim()).filter((part) => part.length > 0)
      : toList(next, []);
    if (sameList(this.#arrays[key] ?? [], value)) return;
    this.#arrays[key] = value;
    this.#reflectList(key, value);
  }

  #reflectList(key: string, value: string[]): void {
    const attribute = toKebabCase(key);
    const fallback = this.#arrayDefaults[key] ?? [];
    this.#reflecting = true;
    try {
      if (value.length === 0 || sameList(value, fallback)) this.removeAttribute(attribute);
      else this.setAttribute(attribute, value.join(','));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #assign(key: string, next: Primitive, type: string): void {
    const value = type === 'boolean' ? Boolean(next) : type === 'number' ? Number(next) : String(next);
    if (Object.is(this.#values[key], value)) return;
    this.#values[key] = value;
    this.#reflect(key, value);
  }

  #reflect(key: string, value: Primitive): void {
    const attribute = toKebabCase(key);
    this.#reflecting = true;
    try {
      if (typeof value === 'boolean') this.toggleAttribute(attribute, value);
      else if (value === this.#defaults[key]) this.removeAttribute(attribute);
      else this.setAttribute(attribute, String(value));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #coerce(key: string, value: string | null): Primitive {
    const fallback = this.#defaults[key];
    if (typeof fallback === 'boolean') return value !== null;
    if (value === null) return fallback;
    if (typeof fallback === 'number') return Number.isNaN(Number(value)) ? fallback : Number(value);
    return value;
  }

  #adoptStyles(root: ShadowRoot, text: string): void {
    if (!text.trim()) return;
    try {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(text);
      root.adoptedStyleSheets = [sheet];
    } catch {
      if (typeof document === 'undefined') return;
      const style = document.createElement('style');
      style.textContent = text;
      root.prepend(style);
      this.#fallbackStyle = style;
    }
  }
}

/* Hooks: --an-checkbox-size | --an-checkbox-radius | --an-checkbox-accent
   | --an-checkbox-border-color.
   Colours and scales come from @an-ui-kit/tokens, each with a literal fallback;
   the shared reset owns the :host box reset. The checked box is drawn outlined
   (accent border + accent check) so the mark never sits on an accent fill: the
   token set has no "on accent" colour, and `--an-color-bg-1` flips with the
   theme. */

:host {
  display: inline-flex;
  vertical-align: middle;
  color-scheme: light dark;
  font-family: inherit;
  font-size: var(--an-font-size-sm, 0.875rem);
  color: var(--an-color-fg-1, #18181b);
}

:host([data-theme='dark']) {
  color-scheme: dark;
}

:host([data-theme='light']) {
  color-scheme: light;
}

.base {
  display: inline-flex;
  align-items: center;
  gap: var(--an-space-2, 0.5rem);
  cursor: pointer;
  line-height: 1.5;
  -webkit-user-select: none;
  user-select: none;
}

:host([disabled]) .base,
:host([data-form-disabled]) .base {
  cursor: not-allowed;
  opacity: 0.55;
}

/* Focusable but invisible: the box below is the painted control, and clicks are
   routed to this input, so keyboard, IME and AT keep native checkbox semantics. */
.native {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: 0;
  padding: 0;
  opacity: 0;
  pointer-events: none;
}

.control {
  position: relative;
  box-sizing: border-box;
  flex: none;
  width: var(--an-checkbox-size, 1rem);
  height: var(--an-checkbox-size, 1rem);
  border: 1px solid var(--an-checkbox-border-color, var(--an-color-border-1, #d4d4d8));
  border-radius: var(--an-checkbox-radius, var(--an-radius-sm, 0.25rem));
  background-color: var(--an-color-bg-1, #ffffff);
  transition: border-color 120ms ease, background-color 120ms ease;
}

.native:focus-visible + .control {
  outline: 2px solid var(--an-checkbox-accent, var(--an-color-accent-9, #2563eb));
  outline-offset: 2px;
}

:host([checked]) .control {
  border-color: var(--an-checkbox-accent, var(--an-color-accent-9, #2563eb));
}

/* The tick: a rotated L-shaped border, so it scales with --an-checkbox-size. */
:host([checked]) .control::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  box-sizing: border-box;
  width: calc(var(--an-checkbox-size, 1rem) * 0.3);
  height: calc(var(--an-checkbox-size, 1rem) * 0.54);
  border: solid var(--an-checkbox-accent, var(--an-color-accent-9, #2563eb));
  border-width: 0 2px 2px 0;
  transform: translate(-50%, -60%) rotate(45deg);
}

/* Indeterminate wins over checked, exactly like the native control: a dash, not a tick. */
:host([indeterminate]) .control {
  border-color: var(--an-checkbox-accent, var(--an-color-accent-9, #2563eb));
}

:host([indeterminate]) .control::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 60%;
  height: 2px;
  border: 0;
  border-radius: 1px;
  background-color: var(--an-checkbox-accent, var(--an-color-accent-9, #2563eb));
  transform: translate(-50%, -50%);
}

.label {
  color: var(--an-color-fg-1, #18181b);
}

@media (prefers-reduced-motion: reduce) {
  .control {
    transition: none;
  }
}

import checkboxStyles from './an-checkbox.css?inline';
import { AnElement } from '../internal/base';

/** Payload of the `an-checkbox-change` event. */
export interface AnCheckboxChangeDetail {
  /** State of the control after the change. */
  checked: boolean;
  /** Value submitted with the form when the control is checked. */
  value: string;
  /** The native event that triggered the change. */
  originalEvent: Event;
}

/** Shown to the owning form when `required` is set and the box is unchecked. */
const REQUIRED_MESSAGE = '此字段为必填项。';

/** Elements whose clicks a native `<label>` does *not* forward to its control. */
const INTERACTIVE = 'a[href], button, input, select, textarea, summary, [contenteditable]';

/** Escapes text used inside an attribute value. */
function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`);
}

/**
 * `<an-checkbox>` — a boolean form control drawn in the shadow root around a
 * native `<input type="checkbox">`, so focus, Space toggling and the accessible
 * checked state all come from the platform.
 *
 * The default slot is the visible label and lives inside the `<label>` that
 * wraps the input, which is what associates the two.
 *
 * Unlike `<an-input>`'s `value`, `checked` is public state and therefore an
 * attribute-backed property: a user toggle writes the `checked` attribute back,
 * so markup, property and the submitted value never disagree.
 *
 * The host is form-associated. The inner input sits behind a shadow boundary and
 * is not part of the outer `<form>`; the host registers the entry itself:
 * `setFormValue(value)` while checked, `setFormValue(null)` while unchecked, and
 * `setValidity({ valueMissing })` for `required` + unchecked, which is what lets
 * the outer form's constraint validation block submission.
 *
 * @attr {boolean} checked - Checked state; a user toggle writes the attribute back and `form.reset()` restores the mounted initial value. Default: false.
 * @attr {boolean} disabled - Bars interaction, constraint validation and form submission; also mirrored from a disabled ancestor `<fieldset>`. Default: false.
 * @attr {boolean} required - Participates in constraint validation (`valueMissing` when unchecked). Default: false.
 * @attr {boolean} indeterminate - Visual-only mixed state (`aria-checked="mixed"`); the next user click clears it and it is never submitted. Default: false.
 * @attr {string} name - Field name used when the value is submitted with the owning form.
 * @attr {string} value - Value submitted while the box is checked. Default: "on".
 * @slot - Label text of the control.
 * @fires an-checkbox-change - Fired after a user toggle; `detail` carries `checked`, `value` and `originalEvent`.
 * @csspart base - The `<label>` wrapper.
 * @csspart control - The painted box (a decorative sibling of the native input).
 * @csspart label - The slot wrapper.
 * @cssprop --an-checkbox-size - Box edge length; defaults to `1rem`.
 * @cssprop --an-checkbox-radius - Box corner radius; defaults to `--an-radius-sm`.
 * @cssprop --an-checkbox-accent - Checked border and tick colour; defaults to `--an-color-accent-9`.
 * @cssprop --an-checkbox-border-color - Unchecked border colour; defaults to `--an-color-border-1`.
 */
export class AnCheckbox extends AnElement {
  static override styles: string = checkboxStyles;

  /** The host owns the form entry; the inner input lives behind a shadow boundary. */
  static override formAssociated = true;

  static override defaults = {
    checked: false,
    disabled: false,
    required: false,
    indeterminate: false,
    name: '',
    value: 'on',
  };

  declare checked: boolean;
  declare disabled: boolean;
  declare required: boolean;
  declare indeterminate: boolean;
  declare name: string;
  declare value: string;

  /** Reset target: the state the element was mounted with. */
  #initialChecked = false;
  #mounted = false;
  /** Set by `formDisabledCallback` (e.g. a disabled ancestor `<fieldset>`). */
  #formDisabled = false;

  constructor() {
    super();
    // Delegation on the shadow root survives the innerHTML re-render. Clicks are
    // handled in the capture phase: cancelling the label's default activation has
    // to happen before the `<label>` between the root and the target reacts.
    this.shadowRoot!.addEventListener('click', this.#onClick, true);
    this.shadowRoot!.addEventListener('change', this.#onChange);
  }

  /** Remembers the checked state the element was mounted with (the reset target). */
  protected override onConnect(): void {
    if (this.#mounted) return;
    this.#mounted = true;
    this.#initialChecked = this.checked;
    this.#syncForm();
  }

  protected override onFormReset(): void {
    this.checked = this.#initialChecked;
  }

  /** Mirrors a platform-level disable (e.g. ancestor `<fieldset disabled>`). */
  protected override onFormDisabled(disabled: boolean): void {
    this.#formDisabled = disabled;
    // Styling hook only; `disabled` itself stays the author's attribute.
    this.toggleAttribute('data-form-disabled', disabled);
    this.requestUpdate();
  }

  protected render(): string {
    const disabled = this.disabled || this.#formDisabled;
    const attrs =
      ` class="native" type="checkbox"` +
      ` value="${escapeHtml(this.value)}"` +
      (this.name ? ` name="${escapeHtml(this.name)}"` : '') +
      (this.checked ? ' checked' : '') +
      (this.indeterminate ? ' aria-checked="mixed"' : '') +
      (disabled ? ' disabled aria-disabled="true"' : '') +
      (this.required ? ' required aria-required="true"' : '');
    return (
      '<label class="base" part="base">' +
      `<input${attrs}>` +
      '<span class="control" part="control" aria-hidden="true"></span>' +
      '<span class="label" part="label"><slot></slot></span>' +
      '</label>'
    );
  }

  protected override afterRender(): void {
    const input = this.#input;
    if (input) {
      // The markup already carries `checked`; re-assert for the paths that do not
      // re-render (e.g. a native click the platform handled before `change`).
      input.checked = this.checked;
      input.indeterminate = this.indeterminate;
    }
    this.#syncForm();
  }

  /**
   * Routes every click through the native input so one click toggles exactly
   * once: a click that lands on the input is left to the platform, anything else
   * (the label text, the painted box) cancels the label's default activation and
   * forwards a single `input.click()`.
   */
  #onClick = (event: Event): void => {
    if (this.disabled || this.#formDisabled) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    const input = this.#input;
    const target = event.target;
    if (!input || target === input) return;
    // Match a native `<label>`: clicks on interactive content do not reach the control.
    if (target instanceof Element && target.closest(INTERACTIVE)) return;
    event.preventDefault();
    // A label click focuses its control natively; keep that so the keyboard stays
    // on the box after the pointer interaction. The change handler then restores
    // focus across the re-render.
    input.focus({ preventScroll: true });
    input.click();
  };

  #onChange = (event: Event): void => {
    const input = this.#input;
    if (!input || event.target !== input) return;
    if (this.disabled || this.#formDisabled) return;
    const checked = input.checked;
    const value = this.value;
    // Writing the property re-renders the shadow root, so keep focus where it was.
    const focused = this.shadowRoot?.activeElement === input;
    if (this.checked !== checked) this.checked = checked;
    // A user toggle ends the mixed state, exactly like a native
    // `<input type="checkbox">` that clears `indeterminate` when clicked: the host
    // property goes back to false and the inner input is re-synced from it.
    if (this.indeterminate) {
      this.indeterminate = false;
      const current = this.#input;
      if (current) current.indeterminate = false;
    }
    if (focused) this.#input?.focus({ preventScroll: true });

    const detail: AnCheckboxChangeDetail = { checked, value, originalEvent: event };
    this.emit('an-checkbox-change', detail);
  };

  /**
   * Publishes the value and the constraint to the owning form.
   *
   * A disabled control is *barred from constraint validation* and contributes no
   * entry, exactly like a native `<input type="checkbox" disabled>`;
   * `required` + unchecked raises `valueMissing` against the inner input, so the
   * browser reports the message next to the control.
   */
  #syncForm(): void {
    const internals = this.internals;
    if (!internals) return;
    if (this.disabled || this.#formDisabled) {
      internals.setFormValue(null);
      internals.setValidity({});
      return;
    }
    internals.setFormValue(this.checked ? this.value : null);
    if (this.required && !this.checked) {
      internals.setValidity({ valueMissing: true }, REQUIRED_MESSAGE, this.#input ?? undefined);
    } else {
      internals.setValidity({});
    }
  }

  /**
   * Platform parity for form-associated custom elements: the host carries no
   * `validationMessage` of its own, so the message the platform computed is read
   * off the internals here — this is what `<an-field>` displays.
   */
  get validationMessage(): string {
    return this.internals?.validationMessage ?? '';
  }

  /** Platform constraint state; `undefined` when the element has no internals. */
  get validity(): ValidityState | undefined {
    return this.internals?.validity;
  }

  get #input(): HTMLInputElement | null {
    return this.shadowRoot?.querySelector('input') ?? null;
  }
}

import groupStyles from './an-checkbox-group.css?inline';
import { AnElement } from '../internal/base';
import type { AnCheckbox, AnCheckboxChangeDetail } from '../checkbox/an-checkbox';

/** Payload of `an-checkbox-group-change`. */
export interface AnCheckboxGroupEventDetail {
  /** Values selected after the change, in DOM order. */
  value: string[];
  /** The click / keyboard event that triggered the change. */
  originalEvent: Event;
}

/** Shown when `required` is set and nothing is selected. */
const REQUIRED_MESSAGE = '请至少选择一个选项';

/** `&` -> `&amp;`, so attribute text can never break out of the markup. */
function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`);
}

/** True once the child has been upgraded into `AnCheckbox` (its accessors exist). */
function isUpgraded(checkbox: AnCheckbox): boolean {
  return typeof (checkbox as unknown as { checked?: unknown }).checked === 'boolean';
}

/** Same ordered list, or not. */
function sameList(left: readonly string[], right: readonly string[]): boolean {
  return left.length === right.length && left.every((value, index) => value === right[index]);
}

/**
 * `<an-checkbox-group>` — form-associated container for a set of
 * `<an-checkbox>` options.
 *
 * The group owns the selection, the form entry and the constraint validation;
 * each child is a dumb control that only renders a native
 * `<input type="checkbox">`. Children report a toggle with
 * `an-checkbox-change`, after which the group writes their `checked` /
 * `disabled` / roving-tab state back.
 *
 * The native inputs live in separate shadow roots, so the platform cannot tab
 * between them: the group keeps exactly one enabled child tabbable and moves
 * focus with the arrow keys (Home / End jump to the ends). Space toggles the
 * focused child, exactly like a native checkbox.
 *
 * @attr {string} name - Form field name; each selected value is submitted under it.
 * @attr {string} value - Comma-separated selected values (`value="a,b"`); reflected by `.value`.
 * @attr {boolean} disabled - Disables the whole group, including every child.
 * @attr {boolean} required - Requires at least one selection for form submission.
 * @attr {string} label - Visible label of the group; also names the `group` for assistive tech.
 * @attr {('vertical'|'horizontal')} orientation - Stacking direction of the options. Default: "vertical".
 * @attr {number} min - Minimum number of selected options; `0` disables the check.
 * @attr {number} max - Maximum number of selected options; `0` means unlimited.
 * @fires an-checkbox-group-change - Fired when the selection changes; `detail = { value, originalEvent }`.
 * @slot - The `<an-checkbox>` options.
 * @csspart base - Outer wrapper around the label and the options.
 * @csspart label - The visible group label; rendered only when `label` is non-empty.
 * @csspart group - The `role="group"` container holding the options.
 * @cssprop --an-checkbox-group-gap - Gap between options; defaults to `--an-space-2` (0.5rem).
 */
export class AnCheckboxGroup extends AnElement {
  static override formAssociated = true;

  static override styles: string = groupStyles;

  static override defaults = {
    name: '',
    label: '',
    disabled: false,
    required: false,
    orientation: 'vertical',
    min: 0,
    max: 0,
  };

  static override arrayDefaults = {
    value: [] as string[],
  };

  /** Form field name; every selected value is submitted under it. */
  declare name: string;
  /** Visible label of the group; also names the `group` for assistive tech. */
  declare label: string;
  /** Disables the whole group, including every child checkbox. */
  declare disabled: boolean;
  /** Requires at least one selected option for form submission. */
  declare required: boolean;
  /** Stacking direction of the options. */
  declare orientation: 'vertical' | 'horizontal';
  /** Minimum number of selected options; `0` disables the check. */
  declare min: number;
  /** Maximum number of selected options; `0` means unlimited. */
  declare max: number;
  /** Selected values, comma-separated in the `value` attribute. */
  declare value: string[];

  /** A platform-level disable (e.g. an ancestor `<fieldset disabled>`). */
  #formDisabled = false;

  /** Selection at mount, restored by `reset()`. */
  #initialValue: string[] = [];

  /** The initial selection is already latched. */
  #captured = false;

  /** The deferred initial-state capture is already queued. */
  #captureScheduled = false;

  /** Child that owns the single roving tab stop. */
  #roving: AnCheckbox | null = null;

  /** A child's own disabled state, kept apart from the group-imposed one. */
  #intrinsicDisabled = new WeakMap<AnCheckbox, boolean>();

  /** The value this group last wrote to `checkbox.disabled`. */
  #appliedDisabled = new WeakMap<AnCheckbox, boolean>();

  constructor() {
    super();
    const root = this.shadowRoot!;
    root.addEventListener('slotchange', this.#onSlotChange);
    // `keydown`, `focusin` and the checkbox's own event are composed, so they
    // reach the host; delegation keeps working across every re-render.
    this.addEventListener('keydown', this.#onKeydown);
    this.addEventListener('focusin', this.#onFocusIn);
    this.addEventListener('an-checkbox-change', this.#onCheckboxChange);
  }

  protected render(): string {
    const label = this.label;
    // A visible label names the group from inside the shadow root; otherwise the
    // consumer-provided ARIA name is forwarded.
    const name = label ? ' aria-labelledby="group-label"' : this.#forwardedName();
    return (
      `<div class="base" part="base">` +
      (label
        ? `<span class="label" part="label" id="group-label">${escapeHtml(label)}</span>`
        : '') +
      `<div class="group" part="group" role="group"` +
      ` aria-required="${this.required}"${name}><slot></slot></div>` +
      `</div>`
    );
  }

  protected override afterRender(): void {
    const internals = this.internals;
    if (internals) {
      internals.ariaDisabled = this.disabled || this.#formDisabled ? 'true' : null;
      internals.ariaRequired = this.required ? 'true' : null;
    }
    this.#syncChildren();
  }

  protected override onConnect(): void {
    // Children created by the parser may not exist yet while this runs; the
    // deferred capture below sees them even when no `slotchange` is emitted.
    this.#syncChildren();
    // Children connect (and render their inner inputs) after this callback, so
    // re-assert once the whole tree is upgraded: the roving tabindex can only be
    // written when the shadow inputs exist.
    queueMicrotask(() => {
      if (this.isConnected) this.#syncChildren();
    });
  }

  protected override onFormReset(): void {
    this.value = [...this.#initialValue];
    this.requestUpdate();
    // The checkbox children are form-associated too, so the platform resets each
    // of them to its own mounted state right after this callback. Re-assert the
    // group selection once every reset callback has run.
    queueMicrotask(() => {
      if (this.isConnected) this.#syncChildren();
    });
  }

  /** Mirrors a platform-level disable (e.g. an ancestor `<fieldset disabled>`). */
  protected override onFormDisabled(disabled: boolean): void {
    this.#formDisabled = disabled;
    this.requestUpdate();
  }

  /**
   * One row per selected value, all under the same `name`. `getFormData()`
   * therefore appends several entries for a multi-value selection.
   */
  protected override formEntries(): Array<[string, string | File]> {
    if (this.disabled || this.#formDisabled || !this.name) return [];
    return this.#selectedValues().map((value): [string, string] => [this.name, value]);
  }

  /**
   * Platform parity for form-associated custom elements: the host carries no
   * `validationMessage` of its own, so the message the platform computed is read
   * off the internals here — this is what `<an-field>` displays.
   */
  get validationMessage(): string {
    return this.internals?.validationMessage ?? '';
  }

  /** Platform constraint state; `undefined` when the element has no internals. */
  get validity(): ValidityState | undefined {
    return this.internals?.validity;
  }

  /**
   * The `<an-checkbox>` options directly owned by this group, in DOM order.
   * Nested groups keep their own options, so the search stops at the first
   * level.
   */
  #checkboxes(): AnCheckbox[] {
    return Array.from(this.children).filter(
      (child) => child.localName === 'an-checkbox',
    ) as unknown as AnCheckbox[];
  }

  /** Enabled options, the candidates for focus and arrow navigation. */
  #enabled(): AnCheckbox[] {
    return this.#checkboxes().filter((checkbox) => !checkbox.disabled);
  }

  /** Selected values that match an option, in DOM order, without duplicates. */
  #selectedValues(): string[] {
    const selected = new Set(this.value);
    const values: string[] = [];
    for (const checkbox of this.#checkboxes()) {
      if (!selected.has(checkbox.value) || values.includes(checkbox.value)) continue;
      values.push(checkbox.value);
    }
    return values;
  }

  /** Pushes the group state down onto every option. */
  #syncChildren(): void {
    const checkboxes = this.#checkboxes();
    // An explicit value needs no deferred adoption, so the reset target can be
    // latched synchronously — `form.reset()` may run before the microtask does.
    if (
      !this.#captured &&
      this.value.length > 0 &&
      checkboxes.length > 0 &&
      checkboxes.every(isUpgraded)
    ) {
      this.#initialValue = [...this.value];
      this.#captured = true;
    }
    const groupDisabled = this.disabled || this.#formDisabled;
    for (const checkbox of checkboxes) {
      // Before the initial state is captured, an empty value leaves the options
      // alone: a `checked` option in markup is the seed for the group value.
      if (this.#captured) {
        const selected = this.value.includes(checkbox.value);
        if (checkbox.checked !== selected) checkbox.checked = selected;
      }
      this.#applyDisabled(checkbox, groupDisabled);
    }
    this.#applyRoving(checkboxes);
    this.#scheduleCapture();
    this.#syncForm();
  }

  /** Applies the group-imposed disable without losing a child's own state. */
  #applyDisabled(checkbox: AnCheckbox, groupDisabled: boolean): void {
    const applied = this.#appliedDisabled.get(checkbox);
    const current = checkbox.disabled;
    if (applied !== undefined && current !== applied) {
      this.#intrinsicDisabled.set(checkbox, current);
    }
    const intrinsic = this.#intrinsicDisabled.get(checkbox) ?? current;
    const next = groupDisabled || intrinsic;
    if (current !== next) checkbox.disabled = next;
    this.#appliedDisabled.set(checkbox, next);
    this.#intrinsicDisabled.set(checkbox, intrinsic);
  }

  /** Keeps exactly one enabled option tabbable; the tab stop follows focus. */
  #applyRoving(checkboxes: AnCheckbox[]): void {
    const enabled = checkboxes.filter((checkbox) => !checkbox.disabled);
    let roving =
      this.#roving && enabled.includes(this.#roving) ? this.#roving : null;
    if (!roving) roving = enabled.find((checkbox) => checkbox.checked) ?? enabled[0] ?? null;
    this.#roving = roving;
    for (const checkbox of checkboxes) {
      const input = this.#inputOf(checkbox);
      if (!input) continue;
      const tabindex = checkbox === roving ? '0' : '-1';
      if (input.getAttribute('tabindex') !== tabindex) input.setAttribute('tabindex', tabindex);
    }
  }

  /** Moves focus (and the roving tab stop) onto one option. */
  #focusCheckbox(checkbox: AnCheckbox): void {
    this.#roving = checkbox;
    this.#applyRoving(this.#checkboxes());
    this.#inputOf(checkbox)?.focus({ preventScroll: true });
  }

  /**
   * Latches the reset target once every option exists and is upgraded. The
   * parser connects the host before its children, so this runs in a microtask
   * (and again when a late option reports a slot change).
   */
  #capture(): void {
    if (this.#captured) return;
    const checkboxes = this.#checkboxes();
    if (checkboxes.length === 0 || !checkboxes.every(isUpgraded)) return;
    const explicit = this.#selectedValues();
    const initial =
      explicit.length > 0
        ? explicit
        : checkboxes.filter((checkbox) => checkbox.checked).map((checkbox) => checkbox.value);
    this.#initialValue = [...initial];
    this.#captured = true;
    // A `checked` option in markup seeds the value when the attribute is absent.
    if (this.value.length === 0 && initial.length > 0) this.value = initial;
  }

  #scheduleCapture(): void {
    if (this.#captured || this.#captureScheduled) return;
    const checkboxes = this.#checkboxes();
    if (checkboxes.length === 0 || !checkboxes.every(isUpgraded)) return;
    this.#captureScheduled = true;
    queueMicrotask(() => {
      this.#captureScheduled = false;
      if (!this.isConnected) return;
      this.#capture();
      this.#syncChildren();
    });
  }

  /** Keeps the form entry and the constraint state in step with the value. */
  #syncForm(): void {
    const internals = this.internals;
    if (!internals) return;
    if (this.disabled || this.#formDisabled) {
      internals.setFormValue(null);
      internals.setValidity({});
      return;
    }
    const values = this.#selectedValues();
    // The platform entry list is a single slot; keep the attribute spelling and
    // let `getFormData()` expose one entry per value for `<an-form>`.
    internals.setFormValue(values.length > 0 ? values.join(',') : null);

    const anchor = this.#firstInput() ?? undefined;
    if (this.required && values.length === 0) {
      internals.setValidity({ valueMissing: true }, REQUIRED_MESSAGE, anchor);
    } else if (this.min > 0 && values.length < this.min) {
      internals.setValidity(
        { customError: true },
        `至少选择 ${this.min} 项`,
        anchor,
      );
    } else if (this.max > 0 && values.length > this.max) {
      internals.setValidity(
        { customError: true },
        `最多选择 ${this.max} 项`,
        anchor,
      );
    } else {
      internals.setValidity({});
    }
  }

  /** The first option's inner input, used as the focus target of the validity. */
  #firstInput(): HTMLInputElement | null {
    for (const checkbox of this.#checkboxes()) {
      const input = this.#inputOf(checkbox);
      if (input) return input;
    }
    return null;
  }

  /** The inner native input of one option, if it has rendered already. */
  #inputOf(checkbox: AnCheckbox): HTMLInputElement | null {
    return checkbox.shadowRoot?.querySelector('input') ?? null;
  }

  /** The `<an-checkbox>` child whose subtree emitted `event`, if any. */
  #checkboxFromEvent(event: Event): AnCheckbox | null {
    const path = typeof event.composedPath === 'function' ? event.composedPath() : [];
    for (const node of path) {
      if (node instanceof HTMLElement && node.localName === 'an-checkbox' && node.parentElement === this) {
        return node as AnCheckbox;
      }
    }
    return null;
  }

  /** DOM order for known values; values without an option keep their order last. */
  #order(values: readonly string[]): string[] {
    const wanted = new Set(values);
    const ordered: string[] = [];
    for (const checkbox of this.#checkboxes()) {
      if (!wanted.has(checkbox.value) || ordered.includes(checkbox.value)) continue;
      ordered.push(checkbox.value);
    }
    for (const value of values) {
      if (!ordered.includes(value)) ordered.push(value);
    }
    return ordered;
  }

  /** Writes the new selection and announces it when it actually changed. */
  #commit(next: Iterable<string>, originalEvent: Event): void {
    const ordered = this.#order([...next]);
    if (sameList(ordered, this.value)) return;
    this.value = ordered;
    this.emit<AnCheckboxGroupEventDetail>('an-checkbox-group-change', {
      value: [...this.value],
      originalEvent,
    });
  }

  /** Toggles one option from a keyboard activation. */
  #toggle(checkbox: AnCheckbox, originalEvent: Event): void {
    if (this.disabled || this.#formDisabled || checkbox.disabled) return;
    const selected = new Set(this.value);
    if (selected.has(checkbox.value)) selected.delete(checkbox.value);
    else selected.add(checkbox.value);
    this.#commit(selected, originalEvent);
  }

  #onSlotChange = (): void => {
    this.#syncChildren();
  };

  #onCheckboxChange = (event: Event): void => {
    const checkbox = this.#checkboxFromEvent(event);
    if (!checkbox || !isUpgraded(checkbox)) return;
    if (this.disabled || this.#formDisabled) {
      const selected = this.value.includes(checkbox.value);
      if (checkbox.checked !== selected) checkbox.checked = selected;
      return;
    }
    const detail = (event as CustomEvent<AnCheckboxChangeDetail | undefined>).detail;
    const checked = detail?.checked ?? checkbox.checked;
    const selected = new Set(this.value);
    if (checked) selected.add(checkbox.value);
    else selected.delete(checkbox.value);
    this.#commit(selected, detail?.originalEvent ?? event);
  };

  #onFocusIn = (event: Event): void => {
    const checkbox = this.#checkboxFromEvent(event);
    if (!checkbox || checkbox.disabled) return;
    this.#roving = checkbox;
    this.#applyRoving(this.#checkboxes());
  };

  #onKeydown = (event: KeyboardEvent): void => {
    const checkbox = this.#checkboxFromEvent(event);
    if (!checkbox || checkbox.disabled) return;
    // Only the option itself (or its inner input) owns these keys; slotted
    // interactive content keeps its own keyboard behaviour.
    const focused = event.composedPath()[0];
    if (focused !== checkbox && focused !== this.#inputOf(checkbox)) return;

    if (event.key === ' ' || event.key === 'Spacebar') {
      event.preventDefault();
      this.#toggle(checkbox, event);
      return;
    }

    const enabled = this.#enabled();
    const index = enabled.indexOf(checkbox);
    if (index === -1) return;

    let next = -1;
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowDown':
        next = (index + 1) % enabled.length;
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        next = (index - 1 + enabled.length) % enabled.length;
        break;
      case 'Home':
        next = 0;
        break;
      case 'End':
        next = enabled.length - 1;
        break;
      default:
        return;
    }

    const target = enabled[next];
    if (!target) return;
    event.preventDefault();
    this.#focusCheckbox(target);
  };

  /** `aria-label` / `aria-labelledby` only when no visible group label exists. */
  #forwardedName(): string {
    const label = this.getAttribute('aria-label');
    const labelledby = this.getAttribute('aria-labelledby');
    return (
      (label ? ` aria-label="${escapeHtml(label)}"` : '') +
      (labelledby ? ` aria-labelledby="${escapeHtml(labelledby)}"` : '')
    );
  }
}
